1	import { useState, useEffect } from 'react';
2	import { useNavigate, useParams } from 'react-router-dom';
3	import { supabase } from '../../lib/supabase';
4	import { WalletService } from '../../services/walletService';
5	import { ArrowLeft, Check, ChevronRight, Wand2, MapPin, DollarSign, Briefcase, Zap, Calendar, Clock, Globe, Wallet, AlertTriangle } from 'lucide-react';
6	import { useToast } from '../../contexts/ToastContext';
7	import { logError } from '../../lib/logger'
8	
9	export default function CompanyCreateJob() {
10	    const navigate = useNavigate();
11	    const { id } = useParams(); // Add useParams
12	    const isEditing = !!id;
13	    const { addToast } = useToast();
14	
15	    const [step, setStep] = useState(1);
16	    const [loading, setLoading] = useState(false);
17	    const [categories, setCategories] = useState<{ name: string, slug: string }[]>([]);
18	    const [companyBalance, setCompanyBalance] = useState<number>(0);
19	    const [balanceLoading, setBalanceLoading] = useState(true);
20	    const [formData, setFormData] = useState({
21	        title: '',
22	        category: '',
23	        type: 'freelance', // freelance, full-time
24	        description: '',
25	        requirements: '',
26	        location: '',
27	        budget: '',
28	        budget_type: 'hourly', // hourly, daily, project
29	        start_date: '',
30	        scope: 'on-site', // on-site, remote, hybrid
31	        work_start_time: '',
32	        work_end_time: '',
33	        has_lunch: false
34	    });
35	
36	    const [predictedCandidates, setPredictedCandidates] = useState(12);
37	
38	    useEffect(() => {
39	        // Fetch Categories
40	        async function loadCategories() {
41	            const { data } = await supabase.from('job_categories').select('name, slug');
42	            if (data && data.length > 0) {
43	                setCategories(data);
44	            } else {
45	                setCategories([
46	                    { name: 'Tecnologia', slug: 'tech' },
47	                    { name: 'Varejo', slug: 'retail' },
48	                    { name: 'Bares e Restaurantes', slug: 'hospitality' },
49	                    { name: 'Eventos', slug: 'events' },
50	                    { name: 'Construção Civil', slug: 'construction' },
51	                    { name: 'Logística', slug: 'logistics' },
52	                    { name: 'Saúde', slug: 'health' },
53	                    { name: 'Outro', slug: 'other' }
54	                ]);
55	            }
56	        }
57	        loadCategories();
58	        loadCompanyBalance();
59	    }, []);
60	
61	    // Fetch company balance
62	    const loadCompanyBalance = async () => {
63	        setBalanceLoading(true);
64	        try {
65	            const { data: { user } } = await supabase.auth.getUser();
66	            if (user) {
67	                const wallet = await WalletService.getOrCreateWallet(user.id, 'company');
68	                setCompanyBalance(wallet?.balance || 0);
69	            }
70	        } catch (error) {
71	            logError('Error loading balance:', error);
72	        } finally {
73	            setBalanceLoading(false);
74	        }
75	    };
76	
77	    // Fetch Job Data if Editing
78	    useEffect(() => {
79	        if (isEditing) {
80	            fetchJobData();
81	        }
82	    // eslint-disable-next-line react-hooks/exhaustive-deps -- fetchJobData usa state setters estaveis, so precisa re-executar quando id muda
83	    }, [id]);
84	
85	    const fetchJobData = async () => {
86	        try {
87	            const { data: { user } } = await supabase.auth.getUser();
88	            if (!user) { navigate('/login'); return; }
89	
90	            const { data, error } = await supabase
91	                .from('jobs')
92	                .select('*')
93	                .eq('id', id)
94	                .eq('company_id', user.id)
95	                .single();
96	
97	            if (error) throw error;
98	            if (data) {
99	                setFormData({
100	                    title: data.title,
101	                    category: data.category,
102	                    type: data.type,
103	                    description: data.description,
104	                    requirements: data.requirements,
105	                    location: data.location || '',
106	                    budget: data.budget?.toString() || '',
107	                    budget_type: data.budget_type,
108	                    start_date: data.start_date ? data.start_date.split('T')[0] : '',
109	                    scope: data.scope,
110	                    work_start_time: data.work_start_time || '',
111	                    work_end_time: data.work_end_time || '',
112	                    has_lunch: data.has_lunch || false
113	                });
114	            }
115	        } catch (error) {
116	            logError('Error fetching job:', error);
117	            navigate('/company/jobs');
118	        }
119	    };
120	
121	    const calculateHours = (start: string, end: string, lunch: boolean = false) => {
122	        if (!start || !end) return { total: 0, work: 0 };
123	        const [startH, startM] = start.split(':').map(Number);
124	        const [endH, endM] = end.split(':').map(Number);
125	
126	        let total = (endH + endM / 60) - (startH + startM / 60);
127	        if (total < 0) total += 24; // Handle overnight
128	
129	        const work = lunch ? Math.max(0, total - 1) : total;
130	        return {
131	            total: total.toFixed(1).replace('.0', ''),
132	            work: work.toFixed(1).replace('.0', '')
133	        };
134	    };
135	
136	    const updatePrediction = () => {
137	        setPredictedCandidates(prev => prev + Math.floor(Math.random() * 3));
138	    };
139	
140	    const handleNext = () => setStep(step + 1);
141	    const handleBack = () => setStep(step - 1);
142	
143	    const handleSubmit = async () => {
144	        setLoading(true);
145	        try {
146	            const { data: { user } } = await supabase.auth.getUser();
147	            if (!user) throw new Error("Usuário não autenticado");
148	
149	            const budgetAmount = parseFloat(formData.budget) || 0;
150	
151	            // For new jobs, verify balance and reserve escrow
152	            if (!isEditing) {
153	                if (budgetAmount <= 0) {
154	                    addToast('Por favor, defina um valor para a vaga.', 'error');
155	                    setLoading(false);
156	                    return;
157	                }
158	
159	                if (companyBalance < budgetAmount) {
160	                    addToast(`Saldo insuficiente. Voce tem R$ ${companyBalance.toFixed(2)} mas precisa de R$ ${budgetAmount.toFixed(2)}.`, 'error');
161	                    setLoading(false);
162	                    return;
163	                }
164	            }
165	
166	            const payload = {
167	                company_id: user.id,
168	                title: formData.title,
169	                category: formData.category,
170	                type: formData.type,
171	                description: formData.description,
172	                requirements: formData.requirements,
173	                location: formData.location,
174	                budget: budgetAmount,
175	                budget_type: formData.budget_type,
176	                start_date: formData.start_date ? new Date(formData.start_date).toISOString() : null,
177	                scope: formData.scope,
178	                work_start_time: formData.work_start_time,
179	                work_end_time: formData.work_end_time,
180	                has_lunch: formData.has_lunch,
181	                status: 'open'
182	            };
183	
184	            if (isEditing) {
185	                const { error } = await supabase.from('jobs').update(payload).eq('id', id);
186	                if (error) throw error;
187	            } else {
188	                // Create job first
189	                const { data: newJob, error } = await supabase.from('jobs').insert(payload).select().single();
190	                if (error) throw error;
191	
192	                // Reserve escrow for the job
193	                const escrowResult = await WalletService.reserveEscrow(newJob.id, budgetAmount, user.id);
194	                if (!escrowResult.success) {
195	                    // Rollback: delete the job if escrow fails
196	                    await supabase.from('jobs').delete().eq('id', newJob.id);
197	                    throw new Error(escrowResult.error || 'Erro ao reservar pagamento');
198	                }
199	
200	                // Update local balance (exact budget amount, fees already paid on deposit)
201	                setCompanyBalance(prev => prev - budgetAmount);
202	            }
203	
204	            addToast(isEditing ? 'Vaga atualizada com sucesso!' : 'Vaga criada com sucesso!', 'success');
205	            navigate('/company/dashboard');
206	        } catch (error: unknown) {
207	            logError('Error saving job:', error);
208	            addToast(error instanceof Error ? error.message : 'Erro ao salvar vaga. Verifique os dados.', 'error');
209	        } finally {
210	            setLoading(false);
211	        }
212	    };
213	
214	    return (
215	        <div className="max-w-3xl mx-auto animate-in fade-in slide-in-from-bottom-8 duration-500 pb-20">
216	            {/* Header */}
217	            <div className="mb-8 flex items-center justify-between">
218	                <div>
219	                    <button onClick={() => navigate(-1)} className="flex items-center gap-2 text-gray-400 font-bold hover:text-black transition-colors mb-2">
220	                        <ArrowLeft size={16} strokeWidth={3} /> Voltar
221	                    </button>
222	                    <h1 className="text-3xl font-black uppercase tracking-tighter">{isEditing ? 'Editar Vaga' : 'Criar Nova Vaga'}</h1>
223	                </div>
224	                {/* Progress Indicator */}
225	                <div className="flex items-center gap-2">
226	                    {[1, 2, 3].map((s) => (
227	                        <div key={s} className={`w-3 h-3 rounded-full border border-black transition-all ${step >= s ? 'bg-black' : 'bg-transparent'}`} aria-label={`Etapa ${s}${step >= s ? ' concluída' : ''}`} />
228	                    ))}
229	                </div>
230	            </div>
231	
232	            <div className="flex gap-8">
233	                {/* Form Area */}
234	                <div className="flex-1 bg-white border-2 border-black rounded-2xl p-8 shadow-[8px_8px_0px_0px_rgba(0,0,0,0.1)]">
235	
236	                    {/* Step 1: Basic Info */}
237	                    {step === 1 && (
238	                        <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
239	                            <h2 className="text-xl font-black uppercase flex items-center gap-2">
240	                                <Briefcase size={20} /> Informações Básicas
241	                            </h2>
242	
243	                            <div className="space-y-2">
244	                                <label className="text-xs font-bold uppercase tracking-wide">Título da Vaga</label>
245	                                <input
246	                                    type="text"
247	                                    aria-label="Título da Vaga"
248	                                    className="w-full bg-gray-50 border-2 border-transparent focus:border-black outline-none rounded-xl p-3 font-bold text-lg placeholder:text-gray-300 transition-all"
249	                                    placeholder="Ex: Designer UI Senior"
250	                                    value={formData.title}
251	                                    onChange={(e) => setFormData({ ...formData, title: e.target.value })}
252	                                />
253	                            </div>
254	
255	                            <div className="grid grid-cols-2 gap-4">
256	                                <div className="space-y-2">
257	                                    <label className="text-xs font-bold uppercase tracking-wide">Categoria</label>
258	                                    <select
259	                                        aria-label="Categoria"
260	                                        className="w-full bg-gray-50 border-2 border-transparent focus:border-black outline-none rounded-xl p-3 font-bold appearance-none"
261	                                        value={formData.category}
262	                                        onChange={(e) => setFormData({ ...formData, category: e.target.value })}
263	                                    >
264	                                        <option value="">Selecione...</option>
265	                                        {categories.map(cat => (
266	                                            <option key={cat.slug} value={cat.slug}>{cat.name}</option>
267	                                        ))}
268	                                    </select>
269	                                </div>
270	                                <div className="space-y-2">
271	                                    <label className="text-xs font-bold uppercase tracking-wide">Modelo</label>
272	                                    <div className="flex bg-gray-50 rounded-xl p-1 border-2 border-transparent">
273	                                        <button
274	                                            onClick={() => setFormData({ ...formData, type: 'freelance' })}
275	                                            className={`flex-1 py-2 rounded-lg text-xs font-black uppercase transition-all ${formData.type === 'freelance' ? 'bg-black text-white shadow-sm' : 'text-gray-400 hover:text-black'}`}
276	                                        >
277	                                            Freelance
278	                                        </button>
279	                                        <button
280	                                            onClick={() => setFormData({ ...formData, type: 'full-time' })}
281	                                            className={`flex-1 py-2 rounded-lg text-xs font-black uppercase transition-all ${formData.type === 'full-time' ? 'bg-black text-white shadow-sm' : 'text-gray-400 hover:text-black'}`}
282	                                        >
283	                                            Fixo
284	                                        </button>
285	                                    </div>
286	                                </div>
287	                            </div>
288	
289	                            <div className="space-y-2">
290	                                <label className="text-xs font-bold uppercase tracking-wide">Formato de Trabalho</label>
291	                                <div className="grid grid-cols-3 gap-2">
292	                                    {[
293	                                        { id: 'on-site', label: 'Presencial', icon: MapPin },
294	                                        { id: 'remote', label: 'Remoto', icon: Globe },
295	                                        { id: 'hybrid', label: 'Híbrido', icon: Briefcase }
296	                                    ].map(sc => (
297	                                        <button
298	                                            key={sc.id}
299	                                            onClick={() => setFormData({ ...formData, scope: sc.id })}
300	                                            className={`flex flex-col items-center justify-center p-3 rounded-xl border-2 transition-all ${formData.scope === sc.id ? 'border-blue-600 bg-blue-50 text-blue-600' : 'border-gray-100 text-gray-400 hover:border-black'}`}
301	                                        >
302	                                            <sc.icon size={20} />
303	                                            <span className="text-[10px] font-black uppercase mt-1">{sc.label}</span>
304	                                        </button>
305	                                    ))}
306	                                </div>
307	                            </div>
308	                        </div>
309	                    )}
310	
311	                    {/* Step 2: Details */}
312	                    {step === 2 && (
313	                        <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
314	                            <h2 className="text-xl font-black uppercase flex items-center gap-2">
315	                                <Wand2 size={20} /> Detalhes & Requisitos
316	                            </h2>
317	
318	                            <div className="space-y-2">
319	                                <label className="text-xs font-bold uppercase tracking-wide">Descrição Completa</label>
320	                                <textarea
321	                                    aria-label="Descrição Completa"
322	                                    className="w-full h-32 bg-gray-50 border-2 border-transparent focus:border-black outline-none rounded-xl p-3 font-medium text-sm placeholder:text-gray-300 transition-all resize-none"
323	                                    placeholder="Descreva o projeto, responsabilidades e objetivos..."
324	                                    value={formData.description}
325	                                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
326	                                />
327	                            </div>
328	
329	                            <div className="space-y-2">
330	                                <label className="text-xs font-bold uppercase tracking-wide">Requisitos</label>
331	                                <textarea
332	                                    aria-label="Requisitos"
333	                                    className="w-full h-24 bg-gray-50 border-2 border-transparent focus:border-black outline-none rounded-xl p-3 font-medium text-sm placeholder:text-gray-300 transition-all resize-none"
334	                                    placeholder="- React Native&#10;- TypeScript&#10;- Figma"
335	                                    value={formData.requirements}
336	                                    onChange={(e) => {
337	                                        setFormData({ ...formData, requirements: e.target.value });
338	                                        if (e.target.value.length % 10 === 0) updatePrediction();
339	                                    }}
340	                                />
341	                            </div>
342	                        </div>
343	                    )}
344	
345	                    {/* Step 3: Logistics */}
346	                    {step === 3 && (
347	                        <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
348	                            <h2 className="text-xl font-black uppercase flex items-center gap-2">
349	                                <DollarSign size={20} /> Orçamento & Cronograma
350	                            </h2>
351	
352	                            {/* Balance Card */}
353	                            {!isEditing && (() => {
354	                                const budgetVal = parseFloat(formData.budget || '0');
355	                                const insufficientBalance = budgetVal > companyBalance;
356	
357	                                return (
358	                                    <>
359	                                        <div className={`p-4 rounded-xl border-2 flex items-center justify-between ${insufficientBalance
360	                                            ? 'bg-red-50 border-red-300'
361	                                            : 'bg-green-50 border-green-300'
362	                                            }`}>
363	                                            <div className="flex items-center gap-3">
364	                                                <Wallet size={24} className={insufficientBalance ? 'text-red-500' : 'text-green-600'} />
365	                                                <div>
366	                                                    <span className="text-xs font-bold uppercase text-gray-500 block">Seu Saldo Disponivel</span>
367	                                                    <span className={`text-2xl font-black ${insufficientBalance ? 'text-red-600' : 'text-green-700'}`}>
368	                                                        {balanceLoading ? '...' : `R$ ${companyBalance.toFixed(2).replace('.', ',')}`}
369	                                                    </span>
370	                                                </div>
371	                                            </div>
372	                                            {insufficientBalance && (
373	                                                <div className="flex items-center gap-2 text-red-600 text-xs font-bold">
374	                                                    <AlertTriangle size={16} />
375	                                                    <span>Saldo insuficiente</span>
376	                                                </div>
377	                                            )}
378	                                        </div>
379	
380	                                        {/* Budget info - no extra fees */}
381	                                        {budgetVal > 0 && (
382	                                            <div className="bg-gray-50 border-2 border-gray-200 rounded-xl p-4 space-y-2 text-sm">
383	                                                <div className="flex justify-between border-b border-gray-200 pb-2">
384	                                                    <span className="font-black uppercase">Orcamento do servico</span>
385	                                                    <span className="font-black text-lg">R$ {budgetVal.toFixed(2).replace('.', ',')}</span>
386	                                                </div>
387	                                                <p className="text-xs text-gray-400 mt-1">Taxas ja foram cobradas no deposito. O valor debitado do seu saldo e exatamente o orcamento, sem custos extras.</p>
388	                                            </div>
389	                                        )}
390	                                    </>
391	                                );
392	                            })()}
393	
394	                            <div className="grid grid-cols-2 gap-4">
395	                                <div className="space-y-2">
396	                                    <label className="text-xs font-bold uppercase tracking-wide">Tipo de Pagamento</label>
397	                                    <select
398	                                        aria-label="Tipo de Pagamento"
399	                                        className="w-full bg-gray-50 border-2 border-transparent focus:border-black outline-none rounded-xl p-3 font-bold appearance-none"
400	                                        value={formData.budget_type}
401	                                        onChange={(e) => setFormData({ ...formData, budget_type: e.target.value })}
402	                                    >
403	                                        <option value="hourly">Por Hora</option>
404	                                        <option value="daily">Por Dia</option>
405	                                        <option value="project">Projeto Fixo</option>
406	                                    </select>
407	                                </div>
408	                                <div className="space-y-2">
409	                                    <label className="text-xs font-bold uppercase tracking-wide">Valor ({formData.budget_type === 'hourly' ? '/h' : formData.budget_type === 'daily' ? '/dia' : 'Total'})</label>
410	                                    <div className="relative">
411	                                        <span className="absolute left-4 top-3.5 font-black text-gray-400">R$</span>
412	                                        <input
413	                                            type="number"
414	                                            aria-label="Valor do orçamento"
415	                                            className={`w-full bg-gray-50 border-2 border-transparent focus:border-black outline-none rounded-xl py-3 pl-10 pr-4 font-bold text-lg placeholder:text-gray-300 transition-all ${isEditing ? 'opacity-50 cursor-not-allowed' : ''}`}
416	                                            placeholder="0,00"
417	                                            value={formData.budget}
418	                                            onChange={(e) => setFormData({ ...formData, budget: e.target.value })}
419	                                            disabled={isEditing}
420	                                        />
421	                                    </div>
422	                                    {isEditing && (
423	                                        <p className="text-xs text-orange-600 font-bold mt-1">
424	                                            O valor não pode ser alterado após a criação.
425	                                        </p>
426	                                    )}
427	                                </div>
428	                            </div>
429	
430	                            <div className="grid grid-cols-2 gap-4">
431	                                <div className="space-y-2">
432	                                    <label className="text-xs font-bold uppercase tracking-wide">Início</label>
433	                                    <div className="relative">
434	                                        <Calendar className="absolute left-3 top-3.5 text-gray-400" size={20} />
435	                                        <input
436	                                            type="date"
437	                                            aria-label="Data de início"
438	                                            className="w-full bg-gray-50 border-2 border-transparent focus:border-black outline-none rounded-xl py-3 pl-10 pr-4 font-bold transition-all"
439	                                            value={formData.start_date}
440	                                            onChange={(e) => setFormData({ ...formData, start_date: e.target.value })}
441	                                        />
442	                                    </div>
443	                                </div>
444	                            </div>
445	
446	                            {/* Detailed Schedule */}
447	                            <div className="bg-gray-50 border-2 border-dashed border-gray-200 rounded-xl p-4 space-y-4">
448	                                <h3 className="text-sm font-black uppercase flex items-center gap-2 text-gray-500">
449	                                    <Clock size={16} /> Horário de Trabalho
450	                                </h3>
451	                                <div className="grid grid-cols-2 gap-4">
452	                                    <div className="space-y-2">
453	                                        <label className="text-xs font-bold uppercase tracking-wide">Entrada</label>
454	                                        <input
455	                                            type="time"
456	                                            aria-label="Horário de entrada"
457	                                            className="w-full bg-white border-2 border-transparent focus:border-black outline-none rounded-xl p-3 font-bold transition-all"
458	                                            value={formData.work_start_time}
459	                                            onChange={(e) => setFormData({ ...formData, work_start_time: e.target.value })}
460	                                        />
461	                                    </div>
462	                                    <div className="space-y-2">
463	                                        <label className="text-xs font-bold uppercase tracking-wide">Saída</label>
464	                                        <input
465	                                            type="time"
466	                                            aria-label="Horário de saída"
467	                                            className="w-full bg-white border-2 border-transparent focus:border-black outline-none rounded-xl p-3 font-bold transition-all"
468	                                            value={formData.work_end_time}
469	                                            onChange={(e) => setFormData({ ...formData, work_end_time: e.target.value })}
470	                                        />
471	                                    </div>
472	                                </div>
473	                                <div className="flex items-center gap-2">
474	                                    <input
475	                                        type="checkbox"
476	                                        id="lunch"
477	                                        className="w-5 h-5 accent-black rounded"
478	                                        checked={formData.has_lunch}
479	                                        onChange={(e) => setFormData({ ...formData, has_lunch: e.target.checked })}
480	                                    />
481	                                    <label htmlFor="lunch" className="text-sm font-bold cursor-pointer select-none">
482	                                        Intervalo de Almoço (1h)
483	                                    </label>
484	                                </div>
485	
486	                                {/* Calculation Display */}
487	                                {(formData.work_start_time && formData.work_end_time) && (
488	                                    <div className="bg-gray-200 rounded-lg p-3 text-xs font-bold uppercase text-gray-600 flex justify-between">
489	                                        <span>Total: {calculateHours(formData.work_start_time, formData.work_end_time).total}h</span>
490	                                        <span>Trabalho: {calculateHours(formData.work_start_time, formData.work_end_time, formData.has_lunch).work}h</span>
491	                                        <span className={formData.has_lunch ? 'text-black' : 'text-gray-400'}>Almoço: {formData.has_lunch ? '1h' : '0h'}</span>
492	                                    </div>
493	                                )}
494	                            </div>
495	
496	                            <div className="space-y-2">
497	                                <label className="text-xs font-bold uppercase tracking-wide">Localização Específica</label>
498	                                <div className="relative">
