16	function computeWorkerSteps(job: JobApplication): Step[] {
17	    const checkinDone = !!job.worker_checkin_at;
18	    const checkoutDone = !!job.worker_checkout_at;
19	    const companyConfirmed = !!job.company_checkout_confirmed_at;
20	
21	    return [
22	        {
23	            label: 'Chegada registrada',
24	            status: checkinDone ? 'complete' : 'active'
25	        },
26	        {
27	            label: 'Check-out',
28	            status: checkoutDone
29	                ? 'complete'
30	                : checkinDone && !checkoutDone
31	                    ? 'active'
32	                    : 'pending'
33	        },
34	        {
35	            label: 'Aguardando empresa',
36	            status: companyConfirmed
37	                ? 'complete'
38	                : checkoutDone && !companyConfirmed
39	                    ? 'active'
40	                    : 'pending'
41	        }
42	    ];
43	}
