1	/**
2	 * useTeamConnections — hook de UI para o roster "minha equipe" e "minhas lojas".
3	 *
4	 * Dois modos de uso:
5	 *   - papel 'company': lista equipe aceita + conexões pendentes da empresa.
6	 *   - papel 'worker':  lista lojas aceitas + convites de equipe pendentes.
7	 *
8	 * Padrão do projeto: useState + useEffect + supabase direto (Art. 5 — sem React Query).
9	 */
10	
11	import { useState, useEffect, useCallback } from 'react';
12	import { useNavigate } from 'react-router-dom';
13	import { supabase } from '../lib/supabase';
14	import { TeamConnectionService } from '../services/teamConnectionService';
15	import { useToast } from '../contexts/ToastContext';
16	import type { TeamConnection, TeamMember, MyStore, TeamConnectionSource } from '../types';
17	
18	// ---------------------------------------------------------------------------
19	// Hook para EMPRESA — gerenciar "minha equipe"
20	// ---------------------------------------------------------------------------
21	
22	export interface UseCompanyTeamResult {
23	  /** Membros aceitos (com perfil do worker). */
24	  teamMembers: TeamMember[];
25	  /** Convites de equipe pendentes (empresa enviou, aguarda worker). */
26	  pendingConnections: TeamConnection[];
27	  loading: boolean;
28	  /** Adicionar worker via QR/link/phone. */
29	  addWorker: (workerId: string, source: TeamConnectionSource) => Promise<boolean>;
30	  /** Recarregar dados. */
31	  refresh: () => void;
32	}
33	
34	export function useCompanyTeam(): UseCompanyTeamResult {
35	  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
36	  const [pendingConnections, setPendingConnections] = useState<TeamConnection[]>([]);
37	  const [loading, setLoading] = useState(true);
38	  const navigate = useNavigate();
39	  const { addToast } = useToast();
40	
41	  const load = useCallback(async () => {
42	    const {
43	      data: { user },
44	    } = await supabase.auth.getUser();
45	    if (!user) {
46	      navigate('/login');
47	      return;
48	    }
49	
50	    setLoading(true);
51	    const [members, all] = await Promise.all([
52	      TeamConnectionService.listTeamMembers(),
53	      TeamConnectionService.listAllConnections(),
54	    ]);
55	
56	    setTeamMembers(members);
57	    setPendingConnections(all.filter((c) => c.status === 'pending'));
58	    setLoading(false);
59	  }, [navigate]);
60	
61	  useEffect(() => {
62	    let active = true;
63	    void (async () => {
64	      const {
65	        data: { user },
66	      } = await supabase.auth.getUser();
67	      if (!user) {
68	        navigate('/login');
69	        return;
70	      }
71	
72	      setLoading(true);
73	      const [members, all] = await Promise.all([
74	        TeamConnectionService.listTeamMembers(),
75	        TeamConnectionService.listAllConnections(),
76	      ]);
77	
78	      if (!active) return;
79	      setTeamMembers(members);
80	      setPendingConnections(all.filter((c) => c.status === 'pending'));
81	      setLoading(false);
82	    })();
83	    return () => {
84	      active = false;
85	    };
86	  }, [navigate]);
87	
88	  const addWorker = useCallback(
89	    async (workerId: string, source: TeamConnectionSource): Promise<boolean> => {
90	      const result = await TeamConnectionService.addToTeam(workerId, source);
91	
92	      if (result.alreadyExists) {
93	        addToast('Este freela já está na sua equipe.', 'info');
94	        return true;
95	      }
96	      if (result.error) {
97	        addToast(result.error, 'error');
98	        return false;
99	      }
100	
101	      addToast('Convite de equipe enviado! Aguardando aceite do freela.', 'success');
102	      load();
103	      return true;
104	    },
105	    [addToast, load],
106	  );
107	
108	  return { teamMembers, pendingConnections, loading, addWorker, refresh: load };
109	}
110	
111	// ---------------------------------------------------------------------------
112	// Hook para WORKER — "minhas lojas" + convites de equipe pendentes
113	// ---------------------------------------------------------------------------
114	
115	export interface UseWorkerStoresResult {
116	  /** Empresas aceitas ("minhas lojas"). */
117	  myStores: MyStore[];
118	  /** Convites de equipe pendentes (empresa convidou, aguarda aceite do worker). */
119	  pendingConnections: TeamConnection[];
120	  loading: boolean;
121	  /** Aceitar convite de equipe. */
122	  acceptConnection: (connectionId: string) => Promise<boolean>;
123	  /** Bloquear/sair de uma empresa. */
124	  blockConnection: (connectionId: string) => Promise<boolean>;
125	  /** Recarregar dados. */
126	  refresh: () => void;
127	}
128	
129	export function useWorkerStores(): UseWorkerStoresResult {
130	  const [myStores, setMyStores] = useState<MyStore[]>([]);
131	  const [pendingConnections, setPendingConnections] = useState<TeamConnection[]>([]);
132	  const [loading, setLoading] = useState(true);
133	  const navigate = useNavigate();
134	  const { addToast } = useToast();
135	
136	  const load = useCallback(async () => {
137	    const {
138	      data: { user },
139	    } = await supabase.auth.getUser();
140	    if (!user) {
141	      navigate('/login');
142	      return;
143	    }
144	
145	    setLoading(true);
146	    const [stores, pending] = await Promise.all([
147	      TeamConnectionService.listMyStores(),
148	      TeamConnectionService.listPendingConnections(),
149	    ]);
150	
151	    setMyStores(stores);
152	    setPendingConnections(pending);
153	    setLoading(false);
154	  }, [navigate]);
155	
156	  useEffect(() => {
157	    let active = true;
158	    void (async () => {
159	      const {
160	        data: { user },
161	      } = await supabase.auth.getUser();
162	      if (!user) {
163	        navigate('/login');
164	        return;
165	      }
166	
167	      setLoading(true);
168	      const [stores, pending] = await Promise.all([
169	        TeamConnectionService.listMyStores(),
170	        TeamConnectionService.listPendingConnections(),
171	      ]);
172	
173	      if (!active) return;
174	      setMyStores(stores);
175	      setPendingConnections(pending);
176	      setLoading(false);
177	    })();
178	    return () => {
179	      active = false;
180	    };
181	  }, [navigate]);
182	
183	  const acceptConnection = useCallback(
184	    async (connectionId: string): Promise<boolean> => {
185	      const result = await TeamConnectionService.acceptConnection(connectionId);
186	      if (result.error) {
187	        addToast(result.error, 'error');
188	        return false;
189	      }
190	      addToast('Você agora faz parte da equipe!', 'success');
191	      load();
192	      return true;
193	    },
194	    [addToast, load],
195	  );
196	
197	  const blockConnection = useCallback(
198	    async (connectionId: string): Promise<boolean> => {
199	      const result = await TeamConnectionService.blockConnection(connectionId);
200	      if (result.error) {
201	        addToast(result.error, 'error');
202	        return false;
203	      }
204	      addToast('Conexão removida.', 'success');
205	      load();
206	      return true;
207	    },
208	    [addToast, load],
209	  );
210	
211	  return {
212	    myStores,
213	    pendingConnections,
214	    loading,
215	    acceptConnection,
216	    blockConnection,
217	    refresh: load,
218	  };
219	}
