import { useState } from 'react';
import { Users, Link2, Phone, QrCode, Copy, Check, Clock, Star, Briefcase, X, Loader2, UserPlus } from 'lucide-react';
import { useCompanyTeam } from '../../hooks/useTeamConnections';
import { TeamConnectionService } from '../../services/teamConnectionService';
import { useAuth } from '../../contexts/AuthContext';
import type { TeamMember, TeamConnection } from '../../types';

// ---------------------------------------------------------------------------
// Subcomponent: card de membro da equipe
// ---------------------------------------------------------------------------

interface MemberCardProps {
  member: TeamMember;
}

function MemberCard({ member }: MemberCardProps) {
  const { worker } = member;
  const avatarUrl = worker.avatar_url ?? worker.photo_url ?? null;

  return (
    <div className="bg-white border-2 border-black rounded-2xl p-5 flex items-start gap-4 hover:shadow-[6px_6px_0px_0px_rgba(0,0,0,1)] hover:-translate-y-0.5 transition-all">
      {/* Avatar */}
      <div className="w-14 h-14 rounded-xl border-2 border-black overflow-hidden bg-gray-100 flex-shrink-0">
        {avatarUrl ? (
          <img src={avatarUrl} alt={worker.full_name} className="w-full h-full object-cover" />
        ) : (
          <div className="w-full h-full flex items-center justify-center bg-black text-white font-black text-xl">
            {worker.full_name?.[0]?.toUpperCase() ?? '?'}
          </div>
        )}
      </div>

      {/* Info */}
      <div className="flex-1 min-w-0">
        <h3 className="font-black uppercase text-base truncate">{worker.full_name}</h3>
        {worker.primary_role && (
          <p className="text-sm font-bold text-gray-500 uppercase truncate">{worker.primary_role}</p>
        )}
        <div className="flex flex-wrap gap-2 mt-2">
          {typeof worker.rating_average === 'number' && (
            <span className="flex items-center gap-1 text-xs font-bold bg-yellow-50 text-yellow-700 px-2 py-1 rounded-xl border border-yellow-200">
              <Star size={12} fill="currentColor" /> {worker.rating_average.toFixed(1)}
            </span>
          )}
          {typeof worker.completed_jobs_count === 'number' && (
            <span className="flex items-center gap-1 text-xs font-bold bg-gray-100 text-gray-600 px-2 py-1 rounded-xl">
              <Briefcase size={12} /> {worker.completed_jobs_count} jobs
            </span>
          )}
          {worker.city && (
            <span className="text-xs font-bold bg-blue-50 text-blue-700 px-2 py-1 rounded-xl">
              {worker.city}
            </span>
          )}
        </div>
      </div>

      {/* Status badge */}
      <span className="flex-shrink-0 bg-primary-light text-primary text-xs font-black uppercase px-2 py-1 rounded-xl border border-green-200">
        Equipe
      </span>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Subcomponent: card de conexão pendente
// ---------------------------------------------------------------------------

interface PendingCardProps {
  connection: TeamConnection;
}

function PendingCard({ connection }: PendingCardProps) {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const workerData = (connection as any).worker as { full_name?: string; avatar_url?: string; primary_role?: string } | undefined;
  const name = workerData?.full_name ?? 'Freela';

  return (
    <div className="bg-gray-50 border-2 border-dashed border-gray-300 rounded-2xl p-4 flex items-center gap-3">
      <div className="w-10 h-10 rounded-xl bg-gray-200 border-2 border-gray-300 flex items-center justify-center font-black text-gray-500">
        {name[0]?.toUpperCase() ?? '?'}
      </div>
      <div className="flex-1 min-w-0">
        <p className="font-black uppercase text-sm truncate">{name}</p>
        {workerData?.primary_role && (
          <p className="text-xs font-bold text-gray-400 uppercase">{workerData.primary_role}</p>
        )}
      </div>
      <div className="flex items-center gap-1 text-xs font-bold text-yellow-700 bg-yellow-50 px-2 py-1 rounded-xl border border-yellow-200">
        <Clock size={12} /> Aguardando
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Subcomponent: modal "Adicionar freela"
// ---------------------------------------------------------------------------

type AddMethod = 'link' | 'phone';

interface AddWorkerModalProps {
  companyId: string;
  onClose: () => void;
  onAdded: () => void;
  addWorker: (workerId: string, source: 'qr' | 'link' | 'phone') => Promise<boolean>;
}

function AddWorkerModal({ companyId, onClose, onAdded, addWorker }: AddWorkerModalProps) {
  const [method, setMethod] = useState<AddMethod>('link');
  const [phone, setPhone] = useState('');
  const [workerId, setWorkerId] = useState('');
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);

  const { token: _token, url: inviteUrl } = TeamConnectionService.generateInviteToken(companyId);

  const handleCopyLink = async () => {
    try {
      await navigator.clipboard.writeText(inviteUrl);
      setCopied(true);
      setTimeout(() => setCopied(false), 2500);
    } catch {
      // fallback: selecionar o texto
    }
  };

  const handlePhoneSubmit = async () => {
    if (!workerId.trim()) return;
    setLoading(true);
    const ok = await addWorker(workerId.trim(), 'phone');
    setLoading(false);
    if (ok) {
      onAdded();
      onClose();
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 bg-black/50 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200"
      onClick={(e) => { if (e.target === e.currentTarget) onClose(); }}
    >
      <div className="bg-white rounded-2xl border-2 border-black shadow-[8px_8px_0px_0px_rgba(0,0,0,1)] w-full max-w-md p-6">
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-black uppercase tracking-tight">Adicionar Freela</h2>
          <button onClick={onClose} aria-label="Fechar" className="p-2 hover:bg-gray-100 rounded-xl transition-colors">
            <X size={20} />
          </button>
        </div>

        {/* Tabs */}
        <div className="flex gap-2 mb-6 border-b-2 border-gray-200 pb-1">
          {([
            { id: 'link' as AddMethod, icon: Link2, label: 'Link' },
            { id: 'phone' as AddMethod, icon: Phone, label: 'Telefone' },
          ] as const).map((tab) => (
            <button
              key={tab.id}
              onClick={() => setMethod(tab.id)}
              className={`flex items-center gap-2 px-4 py-2 rounded-t-xl font-black uppercase text-sm transition-all ${
                method === tab.id
                  ? 'bg-black text-white translate-y-[2px]'
                  : 'text-gray-400 hover:text-black hover:bg-gray-100'
              }`}
            >
              <tab.icon size={16} /> {tab.label}
            </button>
          ))}
          {/* QR: destaque como "em breve" */}
          <button
            disabled
            className="flex items-center gap-2 px-4 py-2 rounded-t-xl font-black uppercase text-sm text-gray-300 cursor-not-allowed"
            title="Scanner QR disponível na v1.1"
          >
            <QrCode size={16} /> QR (v1.1)
          </button>
        </div>

        {/* Conteúdo por método */}
        {method === 'link' && (
          <div className="space-y-4">
            <p className="text-sm font-bold text-gray-600">
              Compartilhe este link com o freela. Ele abrirá o Worki e aceitará o convite de entrada na sua equipe.
            </p>
            <div className="bg-gray-50 border-2 border-black rounded-xl p-4 flex items-center gap-3 font-mono text-xs break-all text-gray-700">
              <span className="flex-1">{inviteUrl}</span>
            </div>
            <button
              onClick={handleCopyLink}
              className="w-full bg-black hover:bg-primary text-white px-6 py-3 rounded-xl font-black uppercase flex items-center justify-center gap-2 transition-colors"
            >
              {copied ? <Check size={18} /> : <Copy size={18} />}
              {copied ? 'Copiado!' : 'Copiar Link'}
            </button>
            <p className="text-xs text-gray-400 text-center">
              O freela aparecerá em "Aguardando" até aceitar o convite.
            </p>
          </div>
        )}

        {method === 'phone' && (
          <div className="space-y-4">
            <p className="text-sm font-bold text-gray-600">
              Digite o <span className="font-black">ID do worker</span> (Worki ID) para adicionar diretamente.
              Busca por telefone disponível na v1.1.
            </p>
            <div className="space-y-2">
              <label htmlFor="phone-input" className="text-xs font-bold uppercase tracking-wide">
                Worki ID do freela
              </label>
              <input
                id="phone-input"
                type="text"
                value={phone}
                onChange={(e) => { setPhone(e.target.value); setWorkerId(e.target.value); }}
                placeholder="Cole o ID do freela aqui"
                className="w-full border-2 border-black rounded-xl px-4 py-3 font-bold focus:ring-2 focus:ring-primary outline-none"
              />
            </div>
            <button
              onClick={handlePhoneSubmit}
              disabled={loading || !workerId.trim()}
              className="w-full bg-black hover:bg-primary text-white px-6 py-3 rounded-xl font-black uppercase flex items-center justify-center gap-2 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {loading ? <Loader2 className="animate-spin" size={18} /> : <UserPlus size={18} />}
              {loading ? 'Enviando...' : 'Enviar Convite'}
            </button>
            <p className="text-xs text-gray-400">
              Busca por CPF/telefone disponível na v1.1. Por enquanto, peça o Worki ID ao freela.
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Página principal: CompanyTeam
// ---------------------------------------------------------------------------

export default function CompanyTeam() {
  const { teamMembers, pendingConnections, loading, addWorker, refresh } = useCompanyTeam();
  const { user } = useAuth();
  const [showAddModal, setShowAddModal] = useState(false);

  // Para gerar o token de convite precisamos do company_id (owner_id = user.id → company.id
  // é resolvido no service; para o modal passamos o user.id e o service busca o company_id real).
  // Aqui usamos user.id como proxy para generateInviteToken — o service usa company_id via query.
  const companyIdProxy = user?.id ?? '';

  if (loading) {
    return (
      <div className="max-w-4xl mx-auto space-y-6 animate-pulse pb-20">
        <div className="h-10 bg-gray-200 rounded-xl w-48" />
        <div className="h-12 bg-gray-200 rounded-xl w-40" />
        <div className="space-y-4">
          {[...Array(3)].map((_, i) => (
            <div key={i} className="h-24 bg-gray-200 rounded-2xl" />
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto pb-20 animate-in fade-in slide-in-from-bottom-4 duration-400">
      {/* Header */}
      <div className="flex items-start justify-between mb-8 gap-4 flex-wrap">
        <div>
          <h1 className="text-4xl font-black uppercase tracking-tighter">Minha Equipe</h1>
          <p className="text-gray-500 font-bold mt-1">
            {teamMembers.length} freela{teamMembers.length !== 1 ? 's' : ''} na equipe
            {pendingConnections.length > 0 && (
              <span className="ml-2 text-yellow-600">· {pendingConnections.length} aguardando aceite</span>
            )}
          </p>
        </div>
        <button
          onClick={() => setShowAddModal(true)}
          className="bg-black hover:bg-primary text-white px-6 py-3 rounded-xl font-black uppercase flex items-center gap-2 transition-colors shadow-[4px_4px_0px_0px_rgba(0,166,81,1)]"
        >
          <UserPlus size={20} /> Adicionar Freela
        </button>
      </div>

      {/* Equipe aceita */}
      {teamMembers.length > 0 && (
        <section className="mb-8">
          <h2 className="text-xl font-black uppercase mb-4 flex items-center gap-2">
            <Users size={20} /> Equipe Ativa
          </h2>
          <div className="grid grid-cols-1 gap-4">
            {teamMembers.map((member) => (
              <MemberCard key={member.connection.id} member={member} />
            ))}
          </div>
        </section>
      )}

      {/* Convites pendentes */}
      {pendingConnections.length > 0 && (
        <section className="mb-8">
          <h2 className="text-xl font-black uppercase mb-4 flex items-center gap-2 text-yellow-700">
            <Clock size={20} /> Aguardando Aceite
          </h2>
          <div className="space-y-3">
            {pendingConnections.map((conn) => (
              <PendingCard key={conn.id} connection={conn} />
            ))}
          </div>
        </section>
      )}

      {/* Empty state */}
      {teamMembers.length === 0 && pendingConnections.length === 0 && (
        <div className="text-center py-20 border-2 border-dashed border-gray-200 rounded-2xl bg-gray-50">
          <Users size={48} className="mx-auto mb-4 text-gray-300" />
          <h3 className="text-xl font-black uppercase mb-2">Equipe vazia</h3>
          <p className="text-gray-500 font-bold mb-6 max-w-sm mx-auto">
            Adicione freelas via link de convite, Worki ID ou QR (em breve). Eles aparecerão aqui após aceitarem.
          </p>
          <button
            onClick={() => setShowAddModal(true)}
            className="bg-black hover:bg-primary text-white px-8 py-3 rounded-xl font-black uppercase inline-flex items-center gap-2 transition-colors"
          >
            <UserPlus size={20} /> Adicionar Primeiro Freela
          </button>
        </div>
      )}

      {/* Modal Adicionar */}
      {showAddModal && (
        <AddWorkerModal
          companyId={companyIdProxy}
          onClose={() => setShowAddModal(false)}
          onAdded={refresh}
          addWorker={addWorker}
        />
      )}
    </div>
  );
}

import { useEffect, useState, useCallback } from 'react';
import { supabase } from '../lib/supabase';
import { MapPin, CheckCircle2, Clock, XCircle, Loader2, DollarSign, Star, Play, Square, AlertCircle, Bell, Building2 } from 'lucide-react';
import PageMeta from '../components/PageMeta';
import { useNavigate } from 'react-router-dom';
import { formatDistanceToNow, isToday, parseISO, isWithinInterval, setHours, setMinutes } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import RateModal from '../components/RateModal';
import JobLifecycleStepper from '../components/JobLifecycleStepper';
import { useToast } from '../contexts/ToastContext';
import { logError } from '../lib/logger';
import { useWorkerInvites } from '../hooks/useShiftInvites';
import type { ReviewDirection } from '../types';

type Step = { label: string; status: 'complete' | 'active' | 'pending' }

function computeWorkerSteps(job: JobApplication): Step[] {
    const checkinDone = !!job.worker_checkin_at;
    const checkoutDone = !!job.worker_checkout_at;
    const companyConfirmed = !!job.company_checkout_confirmed_at;

    return [
        {
            label: 'Chegada registrada',
            status: checkinDone ? 'complete' : 'active'
        },
        {
            label: 'Check-out',
            status: checkoutDone
                ? 'complete'
                : checkinDone && !checkoutDone
                    ? 'active'
                    : 'pending'
        },
        {
            label: 'Aguardando empresa',
            status: companyConfirmed
                ? 'complete'
                : checkoutDone && !companyConfirmed
                    ? 'active'
                    : 'pending'
        }
    ];
}

interface JobApplication {
    id: string;
    job_id: string;
    status: string;
    title: string;
    company_id: string;
    company_name: string;
    company_logo: string | null;
    pay: number;
    date: string;
    raw_date: string | null;
    time: string;
    end_time: string | null;
    location: string;
    month: string;
    day: number | string;
    worker_checkin_at: string | null;
    worker_checkout_at: string | null;
    company_checkin_confirmed_at: string | null;
    company_checkout_confirmed_at: string | null;
}

type ActiveTab = 'invites' | 'applied' | 'in_progress' | 'scheduled' | 'history';

export default function MyJobs() {
    const navigate = useNavigate();
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState<ActiveTab>('invites');
    const [jobs, setJobs] = useState<{
        applied: JobApplication[],
        in_progress: JobApplication[],
        scheduled: JobApplication[],
        history: JobApplication[]
    }>({ applied: [], in_progress: [], scheduled: [], history: [] });

    // Rating State
    const [rateModalOpen, setRateModalOpen] = useState(false);
    const [selectedJobToRate, setSelectedJobToRate] = useState<JobApplication | null>(null);
    const [reviewedJobIds, setReviewedJobIds] = useState<Set<string>>(new Set());
    const [actionLoading, setActionLoading] = useState<string | null>(null);
    const { addToast } = useToast();

    // Hook de convites push
    const { pendingInvites, loading: invitesLoading, respondingId, respond } = useWorkerInvites();

    const fetchJobs = useCallback(async () => {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return navigate('/login');

        // Fetch my reviews to know what I've rated
        const { data: myReviews } = await supabase
            .from('reviews')
            .select('job_id')
            .eq('reviewer_id', user.id);

        const reviewedSet = new Set(myReviews?.map(r => r.job_id) || []);
        setReviewedJobIds(reviewedSet);

        const { data, error } = await supabase
            .from('applications')
            .select(`
                id,
                status,
                created_at,
                worker_checkin_at,
                worker_checkout_at,
                company_checkin_confirmed_at,
                company_checkout_confirmed_at,
                job:jobs (
                    id,
                    title,
                    budget,
                    start_date,
                    work_start_time,
                    work_end_time,
                    location,
                    company:companies (
                        id,
                        name,
                        logo_url
                    )
                )
            `)
            .eq('worker_id', user.id)
            // Excluir convites pending — eles ficam na aba Convites via hook
            .not('status', 'eq', 'invited')
            .order('created_at', { ascending: false });

        if (error) {
            logError('Error fetching applications:', error);
        } else {
            const applied: JobApplication[] = [];
            const in_progress: JobApplication[] = [];
            const scheduled: JobApplication[] = [];
            const history: JobApplication[] = [];

            const now = new Date();

            interface ApplicationRow {
                id: string;
                status: string;
                created_at: string;
                worker_checkin_at: string | null;
                worker_checkout_at: string | null;
                company_checkin_confirmed_at: string | null;
                company_checkout_confirmed_at: string | null;
                job: {
                    id: string;
                    title: string;
                    budget: number;
                    start_date: string | null;
                    work_start_time: string | null;
                    work_end_time: string | null;
                    location: string | null;
                    company: {
                        id: string;
                        name: string;
                        logo_url: string | null;
                    } | null;
                } | null;
            }

            (data as unknown as ApplicationRow[]).forEach((app) => {
                const application: JobApplication = {
                    id: app.id,
                    job_id: app.job?.id || '',
                    status: app.status,
                    title: app.job?.title || 'Job Desconhecido',
                    company_id: app.job?.company?.id || '',
                    company_name: app.job?.company?.name || 'Empresa Confidencial',
                    company_logo: app.job?.company?.logo_url ?? null,
                    pay: app.job?.budget || 0,
                    date: app.job?.start_date ? new Date(app.job.start_date).toLocaleDateString('pt-BR') : 'Data a definir',
                    raw_date: app.job?.start_date ?? null,
                    time: app.job?.work_start_time || 'Horário a definir',
                    end_time: app.job?.work_end_time || null,
                    location: app.job?.location || 'Local a definir',
                    month: app.job?.start_date ? new Date(app.job.start_date).toLocaleString('pt-BR', { month: 'short' }).toUpperCase().replace('.', '') : 'MES',
                    day: app.job?.start_date ? new Date(app.job.start_date).getDate() : '00',
                    worker_checkin_at: app.worker_checkin_at,
                    worker_checkout_at: app.worker_checkout_at,
                    company_checkin_confirmed_at: app.company_checkin_confirmed_at,
                    company_checkout_confirmed_at: app.company_checkout_confirmed_at
                };

                const isJobToday = application.raw_date && isToday(parseISO(application.raw_date));
                let isWithinWorkHours = false;

                if (isJobToday && application.time && application.end_time) {
                    try {
                        const [startH, startM] = application.time.split(':').map(Number);
                        const [endH, endM] = application.end_time.split(':').map(Number);

                        const todayDate = new Date();
                        const startTime = setMinutes(setHours(todayDate, startH), startM);
                        let endTime = setMinutes(setHours(todayDate, endH), endM);

                        if (endTime.getTime() <= startTime.getTime()) {
                            endTime = new Date(endTime.getTime() + 24 * 60 * 60 * 1000);
                        }

                        const startBuffer = new Date(startTime.getTime() - 30 * 60 * 1000);
                        const endBuffer = new Date(endTime.getTime() + 60 * 60 * 1000);

                        isWithinWorkHours = isWithinInterval(now, { start: startBuffer, end: endBuffer });
                    } catch (e) {
                        logError('Error parsing work hours:', e);
                    }
                }

                const isInProgress = (app.status === 'hired' && isJobToday && isWithinWorkHours) || app.status === 'in_progress';

                if (app.status === 'pending' || app.status === 'reviewing' || app.status === 'interview') {
                    applied.push(application);
                } else if (isInProgress) {
                    in_progress.push(application);
                } else if (app.status === 'hired') {
                    scheduled.push(application);
                } else if (['completed', 'rejected', 'cancelled', 'declined'].includes(app.status)) {
                    history.push(application);
                }
            });

            setJobs({ applied, in_progress, scheduled, history });
        }
        setLoading(false);
    }, [navigate]);

    useEffect(() => {
        fetchJobs();
    }, [fetchJobs]);

    const handleCancelApplication = async (appId: string) => {
        if (!window.confirm('Tem certeza que deseja cancelar esta candidatura? Esta acao nao pode ser desfeita.')) {
            return;
        }
        setActionLoading(appId);
        try {
            const { error } = await supabase
                .from('applications')
                .update({ status: 'cancelled' })
                .eq('id', appId);

            if (error) throw error;
            addToast('Candidatura cancelada.', 'success');
            await fetchJobs();
        } catch (err) {
            logError('Error cancelling application:', err);
            addToast('Erro ao cancelar candidatura. Tente novamente.', 'error');
        } finally {
            setActionLoading(null);
        }
    };

    const handleCheckin = async (appId: string) => {
        setActionLoading(appId);
        try {
            const { error } = await supabase
                .from('applications')
                .update({
                    worker_checkin_at: new Date().toISOString(),
                    status: 'in_progress'
                })
                .eq('id', appId);

            if (error) throw error;
            await fetchJobs();
        } catch (err) {
            logError('Error checking in:', err);
            addToast('Erro ao fazer check-in. Tente novamente.', 'error');
        } finally {
            setActionLoading(null);
        }
    };

    const handleCheckout = async (appId: string) => {
        setActionLoading(appId);
        try {
            const { error } = await supabase
                .from('applications')
                .update({ worker_checkout_at: new Date().toISOString() })
                .eq('id', appId);

            if (error) throw error;
            await fetchJobs();
        } catch (err) {
            logError('Error checking out:', err);
            addToast('Erro ao fazer check-out. Tente novamente.', 'error');
        } finally {
            setActionLoading(null);
        }
    };

    const handleOpenRateModal = (job: JobApplication) => {
        setSelectedJobToRate(job);
        setRateModalOpen(true);
    };

    // Fix R10: direction explícito ('company' quando worker avalia empresa)
    const handleSubmitRate = async (rating: number, comment: string) => {
        if (!selectedJobToRate) return;

        try {
            const { data: { user } } = await supabase.auth.getUser();
            if (!user) throw new Error('Not authenticated');

            const direction: ReviewDirection = 'company';

            const { error } = await supabase.from('reviews').insert({
                job_id: selectedJobToRate.job_id,
                reviewer_id: user.id,
                reviewed_id: selectedJobToRate.company_id, // empresa sendo avaliada
                direction,
                rating,
                comment
            });

            if (error) throw error;

            setReviewedJobIds(prev => new Set(prev).add(selectedJobToRate.job_id));
            addToast('Avaliação enviada com sucesso!', 'success');
        } catch (error) {
            logError('Error submitting review:', error);
            addToast('Erro ao enviar avaliação.', 'error');
            throw error;
        }
    };

    if (loading) return (
        <div className="flex flex-col gap-6 pb-24 max-w-4xl mx-auto animate-pulse">
            <div className="h-10 bg-gray-200 rounded w-1/3" />
            <div className="flex gap-2">
                {[...Array(5)].map((_, i) => <div key={i} className="h-10 bg-gray-200 rounded-xl w-24" />)}
            </div>
            <div className="space-y-4">
                {[...Array(4)].map((_, i) => (
                    <div key={i} className="h-28 bg-gray-200 rounded-2xl" />
                ))}
            </div>
        </div>
    );

    return (
        <div className="flex flex-col gap-6 pb-24 font-sans text-accent max-w-4xl mx-auto">
            <PageMeta title="Meus Jobs" description="Acompanhe suas candidaturas, trabalhos agendados e histórico na Worki." />

            <header>
                <h2 className="text-4xl font-black uppercase tracking-tighter">Meus Jobs</h2>
            </header>

            {/* Tabs — Convites PRIMEIRO */}
            <div className="flex gap-2 border-b-2 border-gray-200 pb-1 overflow-x-auto scrollbar-hide">
                {[
                    { id: 'invites' as ActiveTab, label: 'Convites', count: pendingInvites.length, urgent: true },
                    { id: 'applied' as ActiveTab, label: 'Candidaturas', count: jobs.applied.length },
                    { id: 'in_progress' as ActiveTab, label: 'Em Andamento', count: jobs.in_progress.length },
                    { id: 'scheduled' as ActiveTab, label: 'Agendados', count: jobs.scheduled.length },
                    { id: 'history' as ActiveTab, label: 'Histórico', count: jobs.history.length }
                ].map((tab) => (
                    <button
                        key={tab.id}
                        onClick={() => setActiveTab(tab.id)}
                        className={`
                            px-6 py-2 rounded-t-xl font-bold uppercase transition-all whitespace-nowrap flex items-center gap-2
                            ${activeTab === tab.id
                                ? 'bg-black text-white translate-y-[2px]'
                                : 'text-gray-400 hover:text-black hover:bg-gray-100'}
                        `}
                    >
                        {tab.label}
                        {tab.count > 0 && (
                            <span className={`text-xs px-1.5 py-0.5 rounded-full font-black ${
                                tab.urgent
                                    ? 'bg-primary text-white animate-pulse'
                                    : tab.id === 'in_progress'
                                        ? 'bg-red-500 text-white animate-pulse'
                                        : 'bg-gray-200 text-gray-700'
                            }`}>
                                {tab.count}
                            </span>
                        )}
                    </button>
                ))}
            </div>

            {/* Content */}
            <div className="grid gap-4">

                {/* ── ABA CONVITES ── */}
                {activeTab === 'invites' && (
                    <>
                        {invitesLoading && (
                            <div className="space-y-4 animate-pulse">
                                {[...Array(2)].map((_, i) => (
                                    <div key={i} className="h-32 bg-gray-200 rounded-2xl" />
                                ))}
                            </div>
                        )}

                        {!invitesLoading && pendingInvites.length === 0 && (
                            <div className="text-center py-16 text-gray-400 bg-gray-50 rounded-2xl border-2 border-dashed border-gray-200">
                                <Bell size={48} className="mx-auto mb-4 opacity-30" />
                                <p className="font-bold text-lg">Nenhum convite pendente.</p>
                                <p className="text-sm mt-2">Quando uma empresa te convidar para um turno, aparecerá aqui.</p>
                            </div>
                        )}

                        {!invitesLoading && pendingInvites.map((invite) => {
                            const job = invite.job;
                            const companyName = (job?.company as { name?: string } | undefined)?.name ?? 'Empresa';
                            const companyLogo = (job?.company as { logo_url?: string | null } | undefined)?.logo_url ?? null;
                            const jobTitle = job?.title ?? 'Turno';
                            const budget = job?.budget ?? 0;
                            const startDate = job?.start_date
                                ? new Date(job.start_date).toLocaleDateString('pt-BR')
                                : 'Data a definir';
                            const startTime = job?.work_start_time ?? '';
                            const endTime = job?.work_end_time ?? '';
                            const location = job?.location ?? 'Local a definir';
                            const isResponding = respondingId === invite.id;

                            return (
                                <div key={invite.id} className="bg-white border-2 border-black rounded-2xl p-6 shadow-[4px_4px_0px_0px_rgba(0,166,81,1)]">
                                    {/* Empresa */}
                                    <div className="flex items-center gap-3 mb-4">
                                        <div className="w-10 h-10 rounded-xl border-2 border-black overflow-hidden bg-gray-100 flex-shrink-0">
                                            {companyLogo ? (
                                                <img src={companyLogo} alt={companyName} className="w-full h-full object-cover" />
                                            ) : (
                                                <div className="w-full h-full flex items-center justify-center">
                                                    <Building2 size={20} className="text-gray-400" />
                                                </div>
                                            )}
                                        </div>
                                        <div>
                                            <p className="text-xs font-bold uppercase text-gray-400">Convite de</p>
                                            <p className="font-black uppercase">{companyName}</p>
                                        </div>
                                        <span className="ml-auto bg-primary-light text-primary text-xs font-black uppercase px-2 py-1 rounded-xl border border-green-200">
                                            Novo convite
                                        </span>
                                    </div>

                                    {/* Detalhes do turno */}
                                    <h3 className="font-black text-xl uppercase mb-3">{jobTitle}</h3>
                                    <div className="flex flex-wrap gap-2 mb-4">
                                        <span className="flex items-center gap-1.5 text-xs font-bold bg-gray-100 text-gray-600 px-3 py-1.5 rounded-xl">
                                            <Clock size={14} /> {startDate}{startTime ? ` · ${startTime}${endTime ? `–${endTime}` : ''}` : ''}
                                        </span>
                                        <span className="flex items-center gap-1.5 text-xs font-bold bg-primary-light text-primary px-3 py-1.5 rounded-xl">
                                            <DollarSign size={14} /> R$ {budget.toFixed(2).replace('.', ',')}
                                        </span>
                                        {location && (
                                            <span className="flex items-center gap-1.5 text-xs font-bold bg-blue-50 text-blue-700 px-3 py-1.5 rounded-xl">
                                                <MapPin size={14} /> {location}
                                            </span>
                                        )}
                                    </div>

                                    {/* Briefing */}
                                    {job?.description && (
                                        <div className="bg-gray-50 border-l-4 border-black rounded-r-xl p-3 mb-4">
                                            <p className="text-xs font-bold uppercase text-gray-400 mb-1">Briefing</p>
                                            <p className="text-sm font-medium text-gray-700 line-clamp-3">{job.description}</p>
                                        </div>
                                    )}

                                    {/* Expiração */}
                                    {invite.invitation_expires_at && (
                                        <p className="text-xs font-bold text-yellow-600 mb-4 flex items-center gap-1">
                                            <Clock size={12} />
                                            Expira {formatDistanceToNow(new Date(invite.invitation_expires_at), { addSuffix: true, locale: ptBR })}
                                        </p>
                                    )}

                                    {/* Ações */}
                                    <div className="flex gap-3">
                                        <button
                                            onClick={() => respond(invite.id, 'accepted')}
                                            disabled={isResponding}
                                            className="flex-1 bg-primary hover:bg-black text-white px-6 py-3 rounded-xl font-black uppercase flex items-center justify-center gap-2 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                                        >
                                            {isResponding ? <Loader2 className="animate-spin" size={18} /> : <CheckCircle2 size={18} />}
                                            Aceitar
                                        </button>
                                        <button
                                            onClick={() => respond(invite.id, 'declined')}
                                            disabled={isResponding}
                                            className="flex-1 bg-white hover:bg-gray-50 text-gray-700 px-6 py-3 rounded-xl font-black uppercase border-2 border-gray-300 flex items-center justify-center gap-2 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                                        >
                                            {isResponding ? <Loader2 className="animate-spin" size={18} /> : <XCircle size={18} />}
                                            Recusar
                                        </button>
                                    </div>
                                    <p className="text-xs text-gray-400 text-center mt-2 font-bold">
                                        Recusar não afeta sua reputação.
                                    </p>
                                </div>
                            );
                        })}
                    </>
                )}

                {/* ── ABA CANDIDATURAS ── */}
                {activeTab === 'applied' && jobs.applied.length === 0 && (
                    <div className="text-center py-12 text-gray-400 bg-gray-50 rounded-2xl border-2 border-dashed border-gray-200">
                        <p className="font-bold">Você não tem candidaturas pendentes.</p>
                        <button onClick={() => navigate('/dashboard')} className="mt-4 text-primary underline font-bold">Buscar Vagas</button>
                    </div>
                )}
                {activeTab === 'applied' && jobs.applied.map((job, i) => (
                    <div key={i} className="bg-white border-2 border-gray-200 p-6 rounded-2xl flex flex-col md:flex-row justify-between items-start md:items-center opacity-80 hover:opacity-100 transition-opacity gap-4">
                        <div>
                            <h3 className="font-black text-xl uppercase mb-1">{job.title}</h3>
                            <p className="text-sm font-bold text-gray-500">{job.company_name} • {job.location}</p>
                            <span className="inline-block mt-2 bg-yellow-100 text-yellow-700 text-xs font-black px-2 py-1 rounded-md uppercase">
                                {job.status === 'pending' ? 'Aguardando' : job.status === 'interview' ? 'Em Entrevista' : 'Em Análise'}
                            </span>
                        </div>
                        <button
                            onClick={() => handleCancelApplication(job.id)}
                            disabled={actionLoading === job.id}
