1	import { Home, Briefcase, User, Wallet, PlusCircle, Users } from 'lucide-react';
2	import { NavLink } from 'react-router-dom';
3	
4	interface BottomNavProps {
5	    type?: 'worker' | 'company';
6	}
7	
8	export default function BottomNav({ type = 'worker' }: BottomNavProps) {
9	    const workerNavItems = [
10	        { icon: Home, label: 'Início', path: '/dashboard' },
11	        { icon: Briefcase, label: 'Vagas', path: '/jobs' },
12	        { icon: Wallet, label: 'Carteira', path: '/wallet' },
13	        { icon: MessageSquare, label: 'Msgs', path: '/messages' }, // Shortened label
14	        { icon: User, label: 'Perfil', path: '/profile' },
15	    ];
16	
17	    const companyNavItems = [
18	        { icon: Home, label: 'Início', path: '/company/dashboard' },
19	        { icon: Users, label: 'Equipe', path: '/company/team' },
20	        { icon: PlusCircle, label: 'Criar', path: '/company/create' },
21	        { icon: Briefcase, label: 'Vagas', path: '/company/jobs' },
22	        { icon: User, label: 'Perfil', path: '/company/profile' },
23	    ];
24	
25	    const navItems = type === 'company' ? companyNavItems : workerNavItems;
26	    const isCompany = type === 'company';
27	
28	    return (
29	        <nav aria-label="Menu de navegacao" className={`md:hidden fixed bottom-0 left-0 w-full bg-white border-t-2 border-black pb-safe z-50 ${isCompany ? 'border-b-4 border-b-blue-600' : 'border-b-4 border-b-primary'}`}>
30	            <div className="flex justify-around items-center h-16 px-1">
31	                {navItems.map((item) => (
32	                    <NavLink
33	                        key={item.path}
34	                        to={item.path}
35	                        aria-label={item.label}
36	                        className={({ isActive }) => `
37	                 flex flex-col items-center justify-center w-full h-full gap-1 p-2
38	                 ${isActive
39	                                ? (isCompany ? 'text-blue-600' : 'text-primary')
40	                                : 'text-gray-400 hover:text-black'}
41	               `}
42	                    >
43	                        {({ isActive }) => (
44	                            <>
45	                                <item.icon size={22} strokeWidth={isActive ? 3 : 2} />
46	                                <span className={`text-[10px] font-black uppercase ${isActive ? (isCompany ? 'text-blue-600' : 'text-primary') : 'text-gray-400'}`}>
47	                                    {item.label}
48	                                </span>
49	                            </>
50	                        )}
51	                    </NavLink>
52	                ))}
53	            </div>
54	        </nav>
55	    );
56	}
